{
  "triples": [
    {
      "subject": "Feature Extraction",
      "predicate": "uses",
      "object": "CNN",
      "object_type": "Model",
      "source_sentence": "We used a CNN as a trainable feature extractor to extract features from the textual data."
    },
    {
      "subject": "Translation",
      "predicate": "uses",
      "object": "Google translator",
      "object_type": "Other",
      "source_sentence": "While usually it is better to work directly with the source language , in this work we translated utterances into English using Google translator."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "Input",
      "object_type": "Concept",
      "source_sentence": "However, the features that CNN builds internally can be extracted and used as input for another, more advanced classifier."
    },
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "local features",
      "object_type": "Concept",
      "source_sentence": "The features it gives are based on a hierarchy of local features, reflecting well the context."
    },
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "classifier",
      "object_type": "Concept",
      "source_sentence": "How- ever, inspired by ideas introduced in the context of computer vision , we, for the first time in the context of NLP, extract the features that CNN builds internally and feed them into a much more advanced classifier."
    },
    {
      "subject": "Experiments",
      "predicate": "uses",
      "object": "SVM",
      "object_type": "Concept",
      "source_sentence": "In our experiments, this was SVM, or roughly its multi -kernel version MKL, which is good at finding the global optimum."
    }
  ]
}

{
  "triples": [
    {
      "subject": "word2vec dictionary",
      "predicate": "trainedOn",
      "object": "100 million word corpus from Google News",
      "object_type": "Dataset",
      "source_sentence": "able word2vec dictionary , trained on a 100 mil- lion word corpus from Google News using the continuous bag of words architecture."
    },
    {
      "subject": "word2vec dictionary",
      "predicate": "produces",
      "object": "300-dimensional vector for each word",
      "object_type": "Other",
      "source_sentence": "This dictionary provides a 300-dimensional vector for each word."
    },
    {
      "subject": "parts of speech",
      "predicate": "produces",
      "object": "6-dimensional binary vector",
      "object_type": "Other",
      "source_sentence": "We used 6 basic parts of speech (noun, verb, adjective, adverb, preposition, conjunction) encoded as a 6- dimensional binary vector."
    },
    {
      "subject": "Tagger",
      "predicate": "uses",
      "object": "Stanford Tagger",
      "object_type": "Other",
      "source_sentence": "We used Stanford Tagger as a part of speech tagger."
    },
    {
      "subject": "input",
      "predicate": "produces",
      "object": "concatenation of three parts",
      "object_type": "Other",
      "source_sentence": "For each input text, the input vectors for the CNN were a concatenation of three parts:"
    }
  ]
}

{
  "triples": [
    {
      "subject": "SVM",
      "predicate": "achieves",
      "object": "79.77% accuracy",
      "object_type": "Metric",
      "source_sentence": "result (79.77%) obtained when CNN was used to extract trainable features for the SVM classifier."
    },
    {
      "subject": "word2vec",
      "predicate": "achieves",
      "object": "best accuracy",
      "object_type": "Metric",
      "source_sentence": "best accuracy was obtained using Google word2vec."
    },
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "penultimate fully connected layer of the CNN",
      "object_type": "Other",
      "source_sentence": "As features of the given text, we used the values of the penultimate, fully connected, layer of the CNN."
    }
  ]
}

{
